import{_ as t}from"./chunks/02.DG6QN1-y.js";import{_ as e,o,c as l,aa as i}from"./chunks/framework.BAs_AphD.js";const m=JSON.parse('{"title":"Management úkolů","description":"","frontmatter":{"title":"Management úkolů","wiki":"cs:tickets:start"},"headers":[],"relativePath":"tickets/index.md","filePath":"tickets/index.md","lastUpdated":1794209661000}'),r={name:"tickets/index.md"};function d(n,a,s,v,k,p){return o(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="management-ukolu" tabindex="-1">Management úkolů <a class="header-anchor" href="#management-ukolu" aria-label="Permalink to &quot;Management úkolů&quot;">​</a></h1><p>Modul <strong>Management úkolů</strong> slouží k evidenci úkolů, vad a nedodělků, které vznikají při přípravě a realizaci stavby. Úkoly sdílejí členové projektového týmu stavby: kdo má úkol řešit, dozví se o něm hned po zadání, a kdo ho zadal, vidí každou změnu.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/novy-ukol">Zadat vadu nebo úkol do výkresu</a>, <a href="/buildary-help-preview/akademie/editace-ukolu">Změnit stav úkolu a odpovědět</a> a <a href="/buildary-help-preview/akademie/seznam-ukolu">Najít úkoly, filtrovat a exportovat je</a> v Akademii.</p><figure class="shot" style="--w:760px;"><img src="'+t+'" alt="Seznam úkolů s filtry, tlačítkem Nový úkol a přepínačem Tabulka a Kanban" loading="lazy"></figure><h2 id="co-modul-umi" tabindex="-1">Co modul umí <a class="header-anchor" href="#co-modul-umi" aria-label="Permalink to &quot;Co modul umí&quot;">​</a></h2><ul><li>Úkoly zadáte ve webové i v mobilní aplikaci, přímo do výkresu nebo do mapy, v mobilu i z fotografie.</li><li>Úkol můžete založit k záznamu ve stavebním deníku – zůstane se záznamem propojený. Krok za krokem: <a href="/buildary-help-preview/akademie/ukol-k-zaznamu">Založit úkol k zápisu v deníku</a> v Akademii.</li><li>Úkoly třídíte do kategorií, označujete štítky a Řešitele a Schvalovatele může doplnit pravidlo.</li><li>O nových a změněných úkolech vás Buildary informuje notifikacemi ve webové aplikaci, e-mailem a oznámeními v mobilní aplikaci – viz <a href="/buildary-help-preview/tickets/notification">Upozornění na úkoly</a>.</li><li>Úkoly prohlížíte v seznamu, v Kanbanu, ve výkresech a v mapě, v grafech na dashboardu a exportujete je do Excelu nebo PDF.</li></ul><h2 id="zivot-ukolu" tabindex="-1">Život úkolu <a class="header-anchor" href="#zivot-ukolu" aria-label="Permalink to &quot;Život úkolu&quot;">​</a></h2><ol><li><strong>Zadání</strong> – Zadavatel vyplní předmět, popis, kategorii, prioritu, termín a místo ve výkresu nebo v mapě a určí Řešitele a Schvalovatele.</li><li><strong>Řešení</strong> – Řešitel mění stav úkolu (například <strong>Probíhá</strong>, <strong>Čeká se</strong>, <strong>Dokončeno</strong>) a do vyjádření píše, co udělal, i s fotkami.</li><li><strong>Schválení</strong> – Schvalovatel dokončený úkol zkontroluje a schválí, nebo zamítne.</li></ol><p>Kdo kdy co změnil, zůstává v historii úkolu.</p><h2 id="role-u-ukolu" tabindex="-1">Role u úkolu <a class="header-anchor" href="#role-u-ukolu" aria-label="Permalink to &quot;Role u úkolu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Kdo to je</th><th>Co dělá</th></tr></thead><tbody><tr><td><strong>Zadavatel</strong></td><td>Ten, kdo úkol založil. V detailu úkolu je uveden jako <strong>Autor</strong>.</td><td>Zadává úkol: popíše ho, určí termín a místo a vybere Řešitele a Schvalovatele.</td></tr><tr><td><strong>Řešitel</strong></td><td>Člen projektového týmu vybraný v poli <strong>Řešitelé</strong>.</td><td>Úkol plní, mění jeho stav a píše vyjádření.</td></tr><tr><td><strong>Schvalovatel</strong></td><td>Člen projektového týmu vybraný v poli <strong>Schvalovatelé</strong>.</td><td>Kontroluje výsledek a úkol schválí, nebo zamítne.</td></tr></tbody></table><p>Řešitelů i Schvalovatelů může být u úkolu víc. Přesně, kdo co smí, popisuje <a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a>.</p><h2 id="kde-zacit" tabindex="-1">Kde začít <a class="header-anchor" href="#kde-zacit" aria-label="Permalink to &quot;Kde začít&quot;">​</a></h2><h3 id="pripravit-stavbu" tabindex="-1">Připravit stavbu <a class="header-anchor" href="#pripravit-stavbu" aria-label="Permalink to &quot;Připravit stavbu&quot;">​</a></h3><p>Stavbu pro úkoly připravuje administrátor stavby.</p><table tabindex="0"><thead><tr><th>Krok</th><th>Kde je popsáno</th></tr></thead><tbody><tr><td>Zapnout modul na stavbě a přidat lidi do týmu</td><td><a href="/buildary-help-preview/tickets/new_project">Zapnout úkoly na stavbě</a>, <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a></td></tr><tr><td>Nahrát výkresy a rozdělit stavbu na části</td><td><a href="/buildary-help-preview/diary/projectparts">Části stavby a výkresy</a></td></tr><tr><td>Upravit kategorie, štítky a pravidla pro Řešitele a Schvalovatele</td><td><a href="/buildary-help-preview/tickets/rules">Kategorie, štítky a pravidla</a></td></tr><tr><td>Určit, kdo smí zadávat úkoly a kdo vidí všechny</td><td><a href="/buildary-help-preview/tickets/permissions">Kdo co smí v úkolech</a></td></tr></tbody></table><h3 id="pracovat-s-ukoly" tabindex="-1">Pracovat s úkoly <a class="header-anchor" href="#pracovat-s-ukoly" aria-label="Permalink to &quot;Pracovat s úkoly&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Chcete</th><th>Kde je popsáno</th></tr></thead><tbody><tr><td>Zadat úkol</td><td><a href="/buildary-help-preview/tickets/task_new">Zadat úkol</a></td></tr><tr><td>Změnit stav, napsat vyjádření, schválit</td><td><a href="/buildary-help-preview/tickets/task_edit">Řešit a schválit úkol</a></td></tr><tr><td>Najít úkoly, filtrovat je, pracovat s Kanbanem</td><td><a href="/buildary-help-preview/tickets/task_grid">Seznam úkolů a filtry</a></td></tr><tr><td>Uložit si vlastní uspořádání seznamu</td><td><a href="/buildary-help-preview/tickets/taskviews">Přizpůsobit pohledy</a></td></tr><tr><td>Najít úkoly ve výkresu nebo v mapě</td><td><a href="/buildary-help-preview/tickets/task_drawings">Výkresy a mapa</a></td></tr><tr><td>Mít přehled v grafech</td><td><a href="/buildary-help-preview/tickets/dashboard">Dashboard</a></td></tr><tr><td>Stáhnout úkoly do Excelu nebo PDF</td><td><a href="/buildary-help-preview/tickets/exports">Export úkolů</a></td></tr><tr><td>Nastavit, o čem vám přijde zpráva</td><td><a href="/buildary-help-preview/tickets/notification">Upozornění na úkoly</a></td></tr></tbody></table><h2 id="ukoly-v-mobilu" tabindex="-1">Úkoly v mobilu <a class="header-anchor" href="#ukoly-v-mobilu" aria-label="Permalink to &quot;Úkoly v mobilu&quot;">​</a></h2><p>Úkoly máte ve stejné mobilní aplikaci jako stavební deník – viz <a href="/buildary-help-preview/firstofall/mobile">Mobilní aplikace</a>. Stavbu a modul nejdřív připravte na webu, na stavbě pak v mobilu:</p><ul><li>prohlížíte a upravujete úkoly – viz <a href="/buildary-help-preview/tickets/m_task_grid">Úkoly v mobilu</a>,</li><li>zadáváte nové úkoly, i z fotografie nebo z výkresu – viz <a href="/buildary-help-preview/tickets/m_task_new">Nový úkol v mobilu</a>,</li><li>pracujete i bez signálu – viz <a href="/buildary-help-preview/diary/m_offline">Práce bez signálu</a>.</li></ul>',21)])])}const b=e(r,[["render",d]]);export{m as __pageData,b as default};
